import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        B = []
        for _ in range(M):
            B.append(int(next(iterator)))
    except StopIteration:
        return

    sum_A = sum(A)
    sum_B = sum(B)

    diff = sum_B - sum_A

    if diff % 2 != 0:
        print("-1")
        return

    target_diff = diff // 2

    set_A = set(A)

    found = False
    for b in B:
        needed_a = b - target_diff
        if needed_a in set_A:
            found = True
            break

    if found:
        print("1")
    else:
        print("-1")

if __name__ == "__main__":
    main()
